package glitch

import data.glitch_lib

password_keywords := {"password", "pass", "pwd", "secret", "key", "token", "credential", "admin_password", "db_password", "api_password", "auth_password"}

contains_name(name) {
    kw := password_keywords[_]
    glitch_lib.contains(name, kw)
}

check_hardcoded_password(name, value) {
    value.ir_type == "String"
    contains_name(name)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    check_hardcoded_password(attr.name, attr.value)
    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password detected - Avoid using static passwords in IaC scripts. (CWE-259)"
    }
}

