package glitch

import data.glitch_lib

password_keywords := {"password", "pass", "pwd", "secret", "key", "token", "credential", "admin_password", "db_password", "api_password", "auth_password"}

contains_password_keyword(key) {
    some kw in password_keywords
    regex.match(sprintf(".*\\b%s\\b.*", [kw]), key)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    some var in glitch_lib.all_variables(parent)
    contains_password_keyword(var.name)
    var.value.ir_type == "String"
    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid embedding static passwords in code. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    some attr in glitch_lib.all_attributes(parent)
    contains_password_keyword(attr.name)
    attr.value.ir_type == "String"
    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid embedding static passwords in code. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, n])
    n.ir_type == "Hash"
    some pair in n.value
    pair.key.ir_type == "String"
    contains_password_keyword(pair.key.value)
    pair.value.ir_type == "String"
    result := {
        "type": "sec_hard_pass",
        "element": pair,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid embedding static passwords in code. (CWE-259)"
    }
}

